function parseCsv(text){let first=String(text??'').replace(/^\ufeff/,'');let sample=first.slice(0,5000).split(/\r?\n/).slice(0,4).join('\n');const counts=[',',';','\t'].map(c=>[c,(sample.match(new RegExp(c==='\t'?'\\t':c===';'?';':',','g'))||[]).length]);counts.sort((a,b)=>b[1]-a[1]);const sep=counts[0][0];let rows=[],cur=[],field='',inQuote=false;for(let i=0;i<first.length;i++){const c=first[i];if(inQuote){if(c==='"'&&first[i+1]==='"'){field+='"';i++;}else if(c==='"')inQuote=false;else field+=c;}else if(c==='"')inQuote=true;else if(c===sep){cur.push(field);field='';}else if(c==='\n'){cur.push(field.replace(/\r$/,''));field='';if(cur.some(x=>x!==''))rows.push(cur);cur=[];}else field+=c;}cur.push(field.replace(/\r$/,''));if(cur.some(x=>x!==''))rows.push(cur);return rows;}
