function renderFindings(){renderWorkActions();const registered=allFindings(),generated=state.derived,all=state.findingMode==='registered'?registered:generated;const sourceRows=state.sources.filter(x=>x.kind==='controles').reduce((n,x)=>n+x.rows,0);$('findingsSummary').innerHTML='<span class="finding-chip"><strong>'+registered.length+'</strong>unieke controles</span><span class="finding-chip"><strong>'+sourceRows+'</strong>bronregels</span><span class="finding-chip"><strong>'+Math.max(0,sourceRows-registered.length)+'</strong>dubbele ID-regels</span><span class="finding-chip"><strong>'+generated.length+'</strong>automatische signalen</span>';$('modeRegistered').classList.toggle('is-active',state.findingMode==='registered');$('modeSignals').classList.toggle('is-active',state.findingMode==='signals');const counts=groupCounts(all,'category');fillSelect('findingsFilter',counts.map(x=>x[0]));const q=normalize($('findingsSearch').value),filter=$('findingsFilter').value;const found=all.filter(x=>(!q||normalize([x.name,x.category,x.explanation].join(' ')).includes(q))&&(!filter||x.category===filter));$('findingsCount').textContent=found.length+(state.findingMode==='registered'?' controles':' signalen');renderList('findingsList',found,'check',140);}
function renderSources(){const meta={...inventoryMetadata,...(state.metadata||{})};const info=$('inventoryInfo');if(info){const date=/^\d{4}-\d{2}-\d{2}$/.test(meta.firstInventoryStarted||'')?new Date(meta.firstInventoryStarted+'T00:00:00').toLocaleDateString('nl-NL',{day:'numeric',month:'long',year:'numeric'}):String(meta.firstInventoryStarted||'');info.textContent='Eerste inventarisatie gestart: '+date+' · Samenstelling: '+meta.compiledBy+'.';}const wrap=$('sourceList');wrap.innerHTML=state.sources.length?state.sources.map(s=>'<div class="source-row"><div><strong>'+esc(s.kind==='financieel'?'ICT-registratie 2026':s.name)+'</strong><small>'+esc(s.info||'')+'</small></div><span class="chip">'+esc(s.kind)+'</span><span class="result-count">'+s.rows+' rijen</span></div>').join(''):'<div class="no-results">Nog geen bronnen toegevoegd.</div>';$('policyDocs').innerHTML=array(state.policyDocs).length?array(state.policyDocs).map(x=>'<div class="source-row"><div><strong>'+esc(x.name)+'</strong><small>'+esc(x.purpose||'')+'</small></div><span class="chip caution">'+esc(short(x.status||'Niet vastgesteld',42))+'</span></div>').join(''):'<div class="no-results">Geen beleidstukken in de bronnen gevonden.</div>';const legal=$('legalList');legal.innerHTML=legalSources.map(x=>'<div class="legal-item"><div><strong>'+esc(x.name)+'</strong><p>'+esc(x.description)+'</p></div><a href="'+esc(x.url)+'" target="_blank" rel="noopener noreferrer">Bron bekijken &#8594;</a></div>').join('');}
function selectView(view){if(!viewNames[view])return;state.view=view;for(const el of document.querySelectorAll('[data-view]')){el.classList.toggle('active',el.dataset.view===view);el.setAttribute('aria-current',el.dataset.view===view?'page':'false');}for(const el of document.querySelectorAll('.view'))el.hidden=(el.id!=='view'+view[0].toUpperCase()+view.slice(1));$('crumb').textContent=viewNames[view];$('sectionEyebrow').textContent=view==='overview'?'SCHOOLBREED OVERZICHT':view==='ai'?'AI IN HET ONDERWIJS':'INVENTARISATIE';$('sectionTitle').textContent=viewTitles[view];$('sectionIntro').textContent=sectionTexts[view];$('emptyState').hidden=state.ready||view==='sources';if(!state.ready){for(const el of document.querySelectorAll('.view'))el.hidden=(view!=='sources'||el.id!=='viewSources');}else{if(view==='overview')renderOverview();if(view==='apps')renderApps();if(view==='connections')renderConnections();if(view==='ai')renderAi();if(view==='findings')renderFindings();if(view==='sources')renderSources();}window.scrollTo({top:0,behavior:'instant'});}
