function download(name,blob){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),4000);}
function safeFilename(name){return String(name).replace(/[^a-zA-Z0-9._-]/g,'_');}
function xml(s){return String(s??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&apos;');}
function excelColumn(i){let n=i+1,s='';while(n){n--;s=String.fromCharCode(65+n%26)+s;n=Math.floor(n/26);}return s;}
function worksheetXml(rows){let columns=Math.max(1,...rows.map(x=>x.length)),maxRow=Math.max(1,rows.length);let out='<?xml version="1.0" encoding="UTF-8" standalone="yes"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetViews><sheetView workbookViewId="0"><pane ySplit="1" topLeftCell="A2" activePane="bottomLeft" state="frozen"/></sheetView></sheetViews><sheetFormatPr defaultRowHeight="18"/><cols>';for(let i=0;i<columns;i++)out+='<col min="'+(i+1)+'" max="'+(i+1)+'" width="'+(i===0?18:Math.min(62,i<3?31:43))+'" customWidth="1"/>';out+='</cols><sheetData>';
 for(let ri=0;ri<rows.length;ri++){out+='<row r="'+(ri+1)+'"'+(ri===0?' ht="26" customHeight="1"':'')+'>';const row=rows[ri];for(let ci=0;ci<row.length;ci++){const val=row[ci];if(val===''||val===null||val===undefined)continue;const cell=excelColumn(ci)+(ri+1),header=ri===0?' s="1"':'';if(typeof val==='number'&&Number.isFinite(val)){out+='<c r="'+cell+'"'+header+'><v>'+val+'</v></c>';}else{out+='<c r="'+cell+'" t="inlineStr"'+header+'><is><t xml:space="preserve">'+xml(val)+'</t></is></c>';}}out+='</row>';}out+='</sheetData><autoFilter ref="A1:'+excelColumn(columns-1)+maxRow+'"/></worksheet>';return out;}
const crcTable=new Uint32Array(256);for(let n=0;n<256;n++){let c=n;for(let k=0;k<8;k++)c=c&1?0xedb88320^(c>>>1):c>>>1;crcTable[n]=c>>>0;}
function crc32(bytes){let crc=0xffffffff;for(let i=0;i<bytes.length;i++)crc=crcTable[(crc^bytes[i])&255]^(crc>>>8);return(crc^0xffffffff)>>>0;}
function w16(out,off,n){out[off]=n&255;out[off+1]=n>>>8&255;}function w32(out,off,n){out[off]=n&255;out[off+1]=n>>>8&255;out[off+2]=n>>>16&255;out[off+3]=n>>>24&255;}
function zipWrite(files){const entries=files.map(([name,content])=>({name:new TextEncoder().encode(name),data:new TextEncoder().encode(content)}));let length=22,localLength=0;for(const e of entries){length+=30+e.name.length+e.data.length+46+e.name.length;localLength+=30+e.name.length+e.data.length;}const b=new Uint8Array(length);let p=0,cdir=[];for(const e of entries){const off=p,crc=crc32(e.data);w32(b,p,0x04034b50);w16(b,p+4,20);w16(b,p+6,0x800);w16(b,p+8,0);w32(b,p+14,crc);w32(b,p+18,e.data.length);w32(b,p+22,e.data.length);w16(b,p+26,e.name.length);w16(b,p+28,0);p+=30;b.set(e.name,p);p+=e.name.length;b.set(e.data,p);p+=e.data.length;cdir.push({offset:off,crc,...e});}const dirStart=p;for(const e of cdir){w32(b,p,0x02014b50);w16(b,p+4,20);w16(b,p+6,20);w16(b,p+8,0x800);w16(b,p+10,0);w32(b,p+16,e.crc);w32(b,p+20,e.data.length);w32(b,p+24,e.data.length);w16(b,p+28,e.name.length);w16(b,p+30,0);w16(b,p+32,0);w16(b,p+34,0);w16(b,p+36,0);w32(b,p+38,0);w32(b,p+42,e.offset);p+=46;b.set(e.name,p);p+=e.name.length;}const size=p-dirStart;w32(b,p,0x06054b50);w16(b,p+8,entries.length);w16(b,p+10,entries.length);w32(b,p+12,size);w32(b,p+16,dirStart);return new Blob([b],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'});}
/* Compact, narrative-first workbook. Source data remains in memory and in the JSON backup. */
const REPORT_TABS=['Schoolbreed','AI in de klas','AI in de school','Controle & bronnen'];
const RCOLS=10;
function reportSheet(name){return {name,rows:[],merges:[],links:[],filter:null};}
function rr(sheet,values=[],style='plain',opts={}){const r={values,style,height:opts.height||0,hidden:!!opts.hidden,outline:opts.outline||0,styles:opts.styles||{},collapsed:!!opts.collapsed};sheet.rows.push(r);return sheet.rows.length;}
function rm(sheet,row,c1,c2){if(c1<c2)sheet.merges.push([row,c1,row,c2]);}
function rtitle(sheet,name,subtitle){let n=rr(sheet,[name],'title',{height:45});rm(sheet,n,1,10);n=rr(sheet,[subtitle],'subtitle',{height:39});rm(sheet,n,1,10);rr(sheet,[],'blank',{height:10});const nav=rr(sheet,['SCHOOLBREED',null,'AI IN DE KLAS',null,'AI IN DE SCHOOL',null,'CONTROLE & BRONNEN'],'nav',{height:29});for(let c=1;c<=7;c+=2)rm(sheet,nav,c,c+1);for(const [c,dest] of [[1,'Schoolbreed'],[3,'AI in de klas'],[5,'AI in de school'],[7,'Controle & bronnen']])sheet.links.push({r:nav,c,location:"'"+dest+"'!A1"});rr(sheet,[],'blank',{height:11});}
function rsection(sheet,title,subtitle=''){let n=rr(sheet,[title],'section',{height:30});rm(sheet,n,1,10);if(subtitle){n=rr(sheet,[subtitle],'note',{height:Math.min(68,26+Math.floor(subtitle.length/130)*14)});rm(sheet,n,1,10);}rr(sheet,[],'blank',{height:7});}
function rkpis(sheet,data){const row1=new Array(10).fill(null),row2=[...row1],row3=[...row1];data.slice(0,4).forEach((x,i)=>{const c=i*2;row1[c]=x[0];row2[c]=x[1];row3[c]=x[2];});const a=rr(sheet,row1,'kpilabel',{height:23});const b=rr(sheet,row2,'kpivalue',{height:39});const c=rr(sheet,row3,'kpihint',{height:35});for(let col=1;col<=7;col+=2){rm(sheet,a,col,col+1);rm(sheet,b,col,col+1);rm(sheet,c,col,col+1);}rr(sheet,[],'blank',{height:13});}
function rbar(sheet,items,maxRows=8){const ordered=items.filter(e=>e[1]>0).sort((a,b)=>b[1]-a[1]).slice(0,maxRows);const max=Math.max(1,...ordered.map(e=>e[1]));for(const [label,n] of ordered){const vals=[String(label),null,null,n],styles={};for(let c=4;c<10;c++)styles[c]=c-3<=Math.max(1,Math.round(6*n/max))?'barOn':'barOff';const row=rr(sheet,vals,'barrow',{height:27,styles});rm(sheet,row,1,3);}rr(sheet,[],'blank',{height:13});}
function rsource(sheet,body){const n=rr(sheet,[body],'note',{height:Math.min(64,25+Math.floor(body.length/150)*15)});rm(sheet,n,1,10);}
function rtableHeader(sheet,headers){return rr(sheet,headers,'header',{height:32});}
function rline(sheet,cols,height=54){return rr(sheet,cols,'data',{height});}
function rdetail(sheet,label,value,hidden=false){if(value===undefined||value===null||String(value).trim()==='')return;const text=String(value),h=Math.min(240,Math.max(27,22+Math.ceil(text.length/104)*16));const n=rr(sheet,[label,null,text],'detail',{height:h,hidden,outline:1});rm(sheet,n,1,2);rm(sheet,n,3,10);}
function rgroup(sheet,id,label,sub='',visible=false){const a=rr(sheet,[id,null,label],'group',{height:30,collapsed:!visible});rm(sheet,a,1,2);rm(sheet,a,3,10);if(sub)rdetail(sheet,'Onderdeel',sub,!visible);return a;}
function rfeature(sheet,item,isVisible=false){rgroup(sheet,item.id,item.name,[item.product,item.phase,item.local].filter(Boolean).join(' / '),isVisible);
 const fields=[['Wat AI doet',item.action],['Gebruikersgroep',item.users],['Module binnen het platform',item.moduleId],['Proces',item.process],[IctScanTaxonomy.fieldLabel('input',item,'Docent / medewerker stelt in'),item.input],[IctScanTaxonomy.fieldLabel('teacher',item,'Docent / medewerker controleert'),item.teacher],['Wat de leerling doet',item.student],['Leerstrategie / didactisch doel',item.learning],['Didactisch aandachtspunt',item.attention],['Didactische onderbouwing',item.didactics],['Formatief handelen',item.formative],['Niet inzichtelijk of nog te controleren',item.unknown],['Gebruikscontext',item.usageContext],['Instructies leverancier zichtbaar',item.instructions],['Stuurbaarheid',item.steer],['Instelling volgens leverancier',item.defaultSetting],['AI Act-indicatie',item.aiAct],['AI Act-toelichting',item.aiActExplanation],['Lokale status',item.local],['Bron',item.supplierSource||(item.sources||[]).join('; ')]];
 fields.forEach(([a,b])=>rdetail(sheet,a,b,!isVisible));
}
function rsummaryCounts(values,field){const map=new Map();for(const v of values){const label=String(v[field]||'Niet ingedeeld').trim()||'Niet ingedeeld';map.set(label,(map.get(label)||0)+1);}return [...map.entries()];}
function phaseBreakdown(items){const counts=new Map();for(const item of items)for(const phase of IctScanTaxonomy.chartPhases(item))counts.set(phase,(counts.get(phase)||0)+1);return [...counts.entries()];}
function appendAssuranceRows(s){
 rsection(s,'AUTOMATISCHE CONTROLES','Uitslagen gelden voor de gecontroleerde registraties. Geen goedkeuring van een systeem of organisatie.');
 const result=globalThis.IctAssurance?.result();
 if(!result){rsource(s,'Geen actuele controleuitslag beschikbaar. Open Controles en voer de controle uit.');return;}
 const labels={pass:'Geslaagd',attention:'Aandacht',fail:'Afgekeurd',not_run:'Niet uitgevoerd'};
 for(const check of result.checks){rgroup(s,check.id,check.title,labels[check.status]||check.status);for(const item of check.findings)rdetail(s,item.recordId||item.code,item.message,true);}
 rdetail(s,'Controledatum',result.context.asOf,true);rdetail(s,'Gegevensversie',result.context.sourceFingerprint,true);rdetail(s,'Regels',result.rulesetVersion+' / '+result.context.policyId+' '+result.context.policyVersion,true);
}
function assurancePrintSection(){
 const result=globalThis.IctAssurance?.result();
 if(!result)return '<h2>Automatische controles</h2><p>Geen actuele controleuitslag beschikbaar.</p>';
 const labels={pass:'Geslaagd',attention:'Aandacht',fail:'Afgekeurd',not_run:'Niet uitgevoerd'};
 return '<h2>Automatische controles</h2><p>Controledatum: '+esc(result.context.asOf)+'. De uitslagen gelden voor de gecontroleerde registraties.</p>'+result.checks.map(check=>'<p><strong>'+esc(check.title)+'</strong>: '+esc(labels[check.status]||check.status)+'</p>').join('');
}
