function printTable(title,headers,rows,limit=100){let out='<h2>'+esc(title)+'</h2><table><thead><tr>'+headers.map(h=>'<th>'+esc(h)+'</th>').join('')+'</tr></thead><tbody>'+rows.slice(0,limit).map(r=>'<tr>'+r.map(x=>'<td>'+esc(short(x,260))+'</td>').join('')+'</tr>').join('')+'</tbody></table>';if(rows.length>limit)out+='<p>Een deel van de registraties staat uitsluitend in de volledige Excel-export ('+rows.length+' totaal).</p>';return out;}
function printBarSection(title,description,entries,limit=9){const items=entries.filter(x=>x[1]>0).sort((a,b)=>b[1]-a[1]).slice(0,limit),max=Math.max(1,...items.map(x=>x[1]));return '<h2>'+esc(title)+'</h2><p class="section-lead">'+esc(description)+'</p>'+items.map(([k,n])=>'<div class="section-bar"><span>'+esc(k)+'</span><strong>'+n+'</strong><span><i style="width:'+Math.round(100*n/max)+'%"></i></span></div>').join('');}
